class KernelContext {
 public:
  /**
   * 获取kernel的输入数量
   * @return kernel的输入数量
   */
  size_t GetInputNum() const {
    return context_.input_size;
  }
  /**
   * 获取kernel的输出数量
   * @return kernel的输出数量
   */
  size_t GetOutputNum() const {
    return context_.output_size;
  }
