   * 获取输入的Chain指针
   * @param i kernel的输入index
   * @return 输入Chain的指针
   */
  const Chain *GetInput(const size_t i) const {
    if (i >= context_.input_size) {
      return nullptr;
    }
    return reinterpret_cast<const Chain *>(context_.values[i]);
  }
