      return nullptr;
    }
    return reinterpret_cast<const Chain *>(context_.values[context_.input_size + i]);
  }
  Chain *GetOutput2(const size_t i) {
    if (i >= context_.output_size) {
      return nullptr;
    }
    return reinterpret_cast<Chain *>(context_.output_start[i]);
  }
  /**
