   * @tparam T 值的类型
   * @param i kernel的输入index
   * @return 输入的值
   */
  template <typename T>
  const T GetInputValue(size_t i) const {
    const auto av = GetInput(i);
    if (av == nullptr) {
      return {};
    }
    return av->GetValue<T>();
  }
