  const T *GetInputPointer(size_t i) const {
    const auto av = GetInput(i);
    if (av == nullptr) {
      return nullptr;
    }
    return av->GetPointer<T>();
  }
  /**
   * 获取输入数据的指针，本函数首先获取输入Chain，然后从输入Chain中获取指针
   * @tparam T 值的类型
   * @param i kernel的输入index
   * @return 输入数据的指针
   */
